const _raw = $input.first().json;
const payload = (_raw && _raw.data) ? _raw.data : _raw;
const state = Array.isArray(payload) ? payload[0] : payload;
const records = state.records || [];

// Evidence weight by grade. E1 primary/official, E2 trade press, E3 single secondary.
const W = { E1: 1.0, E2: 0.7, E3: 0.4 };
const DIR = { positive: 1, negative: -1, mixed: 0.25, neutral: 0 };

// Signal types that evidence ACTIVE BUYER APPETITE
const DEMAND_TYPES = ['commissioning', 'renewal', 'acquisition', 'development'];
// Signal types that evidence EXISTING SUPPLY (used for saturation)
const SUPPLY_TYPES = ['commissioning', 'renewal', 'production_activity'];

const assertions = [];
let aid = 0;
const mk = (type, obj, ev) => {
  aid++;
  assertions.push(Object.assign({
    assertion_id: 'AS' + String(aid).padStart(4, '0'),
    assertion_type: type,
    evidence_id: ev.evidence_id,
    source_url: ev.source_url,
    evidence_grade: ev.evidence_grade,
    weight: W[ev.evidence_grade] || 0.4
  }, obj));
};

for (const ev of records) {
  const dirv = DIR[ev.direction] !== undefined ? DIR[ev.direction] : 0;

  if (DEMAND_TYPES.includes(ev.signal_type)) {
    for (const b of (ev.buyers.length ? ev.buyers : ['unattributed'])) {
      mk('buyer_demand', { buyer: b, genres: ev.genres, format: ev.format, direction_value: dirv, territory: ev.territory }, ev);
    }
  }

  if (SUPPLY_TYPES.includes(ev.signal_type)) {
    for (const w of ev.worlds) {
      mk('supply', { world: w, genres: ev.genres, engines: ev.engines, titles: ev.titles, format: ev.format }, ev);
    }
    for (const g of ev.genres) {
      mk('genre_supply', { genre: g, format: ev.format, title_count: Math.max(1, ev.titles.length) }, ev);
    }
  }

  if (ev.signal_type === 'audience_data') {
    mk('audience_demand', { genres: ev.genres, metric_name: ev.metric_name, metric_value: ev.metric_value, direction_value: dirv, titles: ev.titles }, ev);
  }

  if (ev.signal_type === 'genre_demand') {
    mk('genre_demand', { genres: ev.genres, metric_name: ev.metric_name, metric_value: ev.metric_value, direction_value: dirv }, ev);
  }

  if (ev.signal_type === 'saturation') {
    mk('saturation', { genres: ev.genres, metric_name: ev.metric_name, metric_value: ev.metric_value, direction_value: dirv, territory: ev.territory }, ev);
  }

  if (ev.signal_type === 'economics' || ev.signal_type === 'funding') {
    mk('economics', { metric_name: ev.metric_name, metric_value: ev.metric_value, direction_value: dirv, interpretation: ev.interpretation, genres: ev.genres, format: ev.format }, ev);
  }

  if (ev.signal_type === 'route' || ev.signal_type === 'open_call') {
    mk('route', { route_type: ev.route_type || 'unspecified', buyers: ev.buyers, direction_value: dirv, metric_name: ev.metric_name, metric_value: ev.metric_value }, ev);
  }

  if (ev.signal_type === 'format_trend') {
    mk('format_trend', { metric_name: ev.metric_name, metric_value: ev.metric_value, direction_value: dirv, interpretation: ev.interpretation, buyers: ev.buyers }, ev);
  }

  if (ev.signal_type === 'industry_structure' || ev.signal_type === 'industry_event') {
    mk('structure', { direction_value: dirv, interpretation: ev.interpretation, buyers: ev.buyers }, ev);
  }

  if (ev.legal_flag) {
    mk('legal_flag', { flag: ev.legal_flag, titles: ev.titles, worlds: ev.worlds }, ev);
  }

  if (ev.source_ip) {
    mk('ip_provenance', { source_ip: ev.source_ip, titles: ev.titles, buyers: ev.buyers }, ev);
  }
}

const byType = {};
for (const a of assertions) byType[a.assertion_type] = (byType[a.assertion_type] || 0) + 1;

return [{ json: {
  stage: 'WF-11',
  generated_at: new Date().toISOString(),
  source_stage: state.stage,
  input_record_count: records.length,
  assertion_count: assertions.length,
  assertions_by_type: byType,
  assertions
} }];
